/**
 * Confere o que a sincronia devolveu.
 *
 * Lançar aqui é de propósito: uma execução vermelha na lista do n8n é
 * o único jeito de a sincronia quebrada aparecer para alguém. Se este
 * nó engolisse o erro, o site seguiria vendendo data que a Airbnb já
 * vendeu, e ninguém descobriria até o cliente reclamar.
 */
const resposta = $input.first().json;

if (resposta.erro) {
  throw new Error(`Sincronia da Airbnb falhou: ${resposta.erro}`);
}

const alertas = resposta.alertas || [];
if (alertas.length > 0) {
  throw new Error(`Sincronia da Airbnb pede atenção: ${alertas.join(' | ')}`);
}

const r = resposta.reservas || {};
const b = resposta.bloqueios || {};

const conta = (lista) => (lista || []).length;
const mudancas =
  conta(r.criadas) + conta(r.atualizadas) + conta(r.canceladas) +
  conta(b.criados) + conta(b.atualizados) + conta(b.removidos);

return [
  {
    json: {
      eventosNaAirbnb: resposta.eventos,
      mudancas,
      reservas: r,
      bloqueios: b,
      avisos: resposta.avisos,
    },
  },
];
